-- AMORAP only. Run in the existing Supabase project's SQL Editor.
-- Does not create, modify or drop any table in public or another schema.
BEGIN;
CREATE SCHEMA IF NOT EXISTS amorap_booking;
CREATE TABLE IF NOT EXISTS amorap_booking.settings (
  key text PRIMARY KEY, value text NOT NULL
);
CREATE TABLE IF NOT EXISTS amorap_booking.reservations (
  id text PRIMARY KEY, token text NOT NULL,
  status text NOT NULL CHECK (status IN ('awaiting_payment','payment_review','confirmed','cancelled','expired')),
  created bigint NOT NULL, expires bigint NOT NULL,
  payload text NOT NULL, reference text NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS amorap_reservations_status_idx ON amorap_booking.reservations (status, expires);
CREATE TABLE IF NOT EXISTS amorap_booking.messages (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created bigint NOT NULL, payload text NOT NULL
);
CREATE TABLE IF NOT EXISTS amorap_booking.photos (
  name text PRIMARY KEY, mime text NOT NULL CHECK (mime IN ('image/jpeg','image/png','image/webp')),
  content bytea NOT NULL CHECK (octet_length(content) <= 6000000)
);
CREATE TABLE IF NOT EXISTS amorap_booking.admin_sessions (
  token text PRIMARY KEY, csrf text NOT NULL, expiry bigint NOT NULL
);
-- No direct access from browser, anon or authenticated API roles.
REVOKE ALL ON SCHEMA amorap_booking FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA amorap_booking FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA amorap_booking FROM PUBLIC, anon, authenticated;
ALTER TABLE amorap_booking.settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE amorap_booking.reservations ENABLE ROW LEVEL SECURITY;
ALTER TABLE amorap_booking.messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE amorap_booking.photos ENABLE ROW LEVEL SECURITY;
ALTER TABLE amorap_booking.admin_sessions ENABLE ROW LEVEL SECURITY;

